HTML = '''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Jogadores e elencos — PES6 Studio</title>
<style>*{box-sizing:border-box}body{background:#10151f;color:#e5edf7;font:15px system-ui;margin:24px;max-width:1350px}a{color:#8fcbff}button,input,select{padding:8px;margin:4px;background:#24344d;color:white;border:1px solid #587192;border-radius:5px}button{cursor:pointer}button:disabled{opacity:.5}section{border-top:1px solid #455670;padding:16px 0}.columns{display:flex;gap:28px;flex-wrap:wrap}.left{width:400px}.right{flex:1;min-width:500px}#list{width:100%;height:260px}label{display:block}td,th{padding:3px;border-bottom:1px solid #33445b;text-align:left}td input{width:65px}#status{min-height:24px;color:#b4e79c}small{color:#b0c1d5}</style>
<nav><a href="/">Galeria</a> · <a href="/clubs">Clubes</a> · <a href="/leagues">Ligas</a> · <a href="/scoreboards">Placares</a></nav>
<h1>Jogadores e elencos</h1><label>Base de dados <select id="database"><option value="6668">6668 — 4.210 registros / 189 elencos</option><option value="6667">6667 — 4.415 registros / 188 elencos</option></select></label><p id="note"></p>
<section><h2>Identificar a base usada no jogo</h2><p>Gere um teste isolado com Lampard marcado como <strong>Lampard DB6667</strong> ou <strong>Lampard DB6668</strong>. Confira o nome no Chelsea/London FC e na Inglaterra. O resultado vale para a tela e o modo testados.</p><button id="probe">Gerar teste isolado da base</button><p><small>O teste usa o modo IMG/ISO selecionado abaixo, preserva suas alterações pendentes e não entra no projeto. Se nenhum marcador aparecer, confira a cópia do jogo e o option file/save utilizado, sem apagar seus saves.</small></p></section><div class="columns"><div class="left"><h2>Jogadores</h2><input id="search" placeholder="Buscar por nome ou ID" aria-label="Buscar jogador"><p id="count"></p><select id="list" size="10" aria-label="Resultados"></select>
<p id="playerid"></p><label>Nome no jogo <input id="name"></label><label>Nome na camisa <input id="shirt"></label><small>Limites: 45 e 15 bytes UTF-8. Os demais atributos são preservados.</small><p><button id="playerSave">Preparar jogador</button><button id="playerUndo">Restaurar jogador</button></p><p id="memberships"></p></div>
<div class="right"><h2>Elenco</h2><select id="team" aria-label="Selecionar elenco"></select><p><small>Confira a identidade pelos jogadores. ↑ e ↓ mudam a ordem e levam o número junto. Essa ordem não edita a formação tática.</small></p><table><thead><tr><th>Posição</th><th>Jogador</th><th>Nº</th><th>Ações</th></tr></thead><tbody id="squad"></tbody></table><button id="squadSave">Preparar elenco</button><button id="squadUndo">Restaurar elenco</button><p><label>Transferir da posição <input id="from" type="number" min="1" max="32" value="1" style="width:65px"></label><label>Para <select id="destination"></select></label><button id="transfer">Transferir para a primeira vaga</button></p><small>A transferência remove o registro do elenco de origem e o insere no destino. Outras inscrições, como seleções, são preservadas.</small></div></div>
<p id="status" role="status"></p><section><button id="save">Salvar projeto</button><button id="load">Carregar projeto</button><select id="mode"><option value="img">Gerar IMG</option><option value="iso">Gerar ISO</option></select><button id="build">Gerar patch</button><button id="open" hidden>Abrir pasta gerada</button><p id="output" role="status"></p></section>
<script>const $=id=>document.getElementById(id);let state,rows=[],dirty=false,currentSlot=0,currentDB=6668,selected=1,dir;const db=()=>Number($('database').value);async function api(url,body){const r=await fetch(url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:typeof body==='string'?body:JSON.stringify(body)});const d=await r.json();if(!r.ok||d.error)throw Error(d.error||r.statusText);return d}async function run(f){try{await f()}catch(e){$('status').textContent=e.message}}function player(id){return state.players.find(p=>p.player_id===id)}function search(){let q=$('search').value.toLocaleLowerCase(),found=state.players.filter(p=>!q||String(p.player_id)===q||p.name.toLocaleLowerCase().includes(q));$('count').textContent=found.length+' encontrados; mostrando até 150';$('list').replaceChildren(...found.slice(0,150).map(p=>new Option(p.player_id+' — '+(p.name||'(sem nome)')+(p.modified?' *':''),p.player_id)));if(found.some(p=>p.player_id===selected))$('list').value=selected;else if(found.length)selected=found[0].player_id;showPlayer()}async function showPlayer(){let p=player(selected);if(!p)return;$('playerid').textContent='ID '+p.player_id+' · base '+db();$('name').value=p.name;$('shirt').value=p.shirt_name;try{let d=await api('/players/memberships?database='+db()+'&id='+selected);$('memberships').textContent='Inscrições nesta base: '+d.slots.map(s=>'elenco '+s).join(', ')}catch(e){$('memberships').textContent=e.message}}function renderRows(){$('squad').replaceChildren(...rows.map((r,i)=>{let tr=document.createElement('tr');let pos=document.createElement('td');pos.textContent=i+1;let name=document.createElement('td');name.textContent=[0,65535].includes(r.player_id)?'— vaga —':r.player_id+' · '+(player(r.player_id)?.name||'(sem nome)');let n=document.createElement('td'),input=document.createElement('input');input.type='number';input.min=0;input.max=255;input.value=r.number;input.setAttribute('aria-label','Número na posição '+(i+1));input.oninput=()=>{r.number=Number(input.value);dirty=true};n.append(input);let actions=document.createElement('td');for(let [label,f] of [['Colocar',()=>{rows[i]={player_id:selected,number:r.number===255?0:r.number}}],['Remover',()=>{rows[i]={player_id:65535,number:255}}],['↑',()=>{if(i)[rows[i-1],rows[i]]=[rows[i],rows[i-1]]}],['↓',()=>{if(i<31)[rows[i+1],rows[i]]=[rows[i],rows[i+1]]}]]){let b=document.createElement('button');b.textContent=label;b.onclick=()=>{f();dirty=true;renderRows()};actions.append(b)}tr.append(pos,name,n,actions);return tr}))}async function squad(){let d=await api('/players/squad?database='+db()+'&slot='+$('team').value);rows=d.rows;currentSlot=Number($('team').value);dirty=false;renderRows()}async function refresh(){state=await api('/players/data?database='+db());currentDB=db();$('note').textContent=state.note;for(let id of ['team','destination']){let old=$(id).value;$(id).replaceChildren(...state.teams.map(t=>new Option('Elenco '+t.slot+(t.reference_name?' · '+t.reference_name+' (referência)':'')+(t.modified?' *':''),t.slot)));if(state.teams.some(t=>String(t.slot)===old))$(id).value=old}search();await squad()}function discard(){return !dirty||confirm('Descartar alterações do elenco ainda não preparadas?')}$('search').oninput=search;$('list').onchange=()=>{selected=Number($('list').value);showPlayer()};$('database').onchange=()=>run(async()=>{if(!discard()){$('database').value=currentDB;return}await refresh()});$('team').onchange=()=>run(async()=>{if(!discard()){$('team').value=currentSlot;return}await squad()});$('playerSave').onclick=()=>run(async()=>{if(!discard())return;await api('/players/name',{database:db(),player_id:selected,name:$('name').value,shirt_name:$('shirt').value});await refresh();$('status').textContent='Jogador preparado.'});$('playerUndo').onclick=()=>run(async()=>{if(!discard())return;await api('/players/nameUndo',{database:db(),player_id:selected});await refresh()});$('squadSave').onclick=()=>run(async()=>{await api('/players/squad',{database:db(),slot:currentSlot,rows});await refresh();$('status').textContent='Elenco preparado.'});$('squadUndo').onclick=()=>run(async()=>{if(!discard())return;await api('/players/squadUndo',{database:db(),slot:currentSlot});await refresh()});$('transfer').onclick=()=>run(async()=>{if(dirty)throw Error('Prepare o elenco antes de transferir.');await api('/players/transfer',{database:db(),source:currentSlot,position:Number($('from').value)-1,target:Number($('destination').value)});await refresh();$('status').textContent='Transferência preparada nos dois elencos.'});$('save').onclick=()=>run(async()=>{if(dirty)throw Error('Prepare o elenco antes de salvar.');$('status').textContent=(await api('/save','')).message});$('load').onclick=()=>run(async()=>{if(!confirm('Substituir as alterações atuais pelo projeto salvo?'))return;await api('/load','');await refresh();$('status').textContent='Projeto carregado.'});$('build').onclick=()=>run(async()=>{if(dirty)throw Error('Prepare o elenco antes de gerar.');try{$('build').disabled=true;$('open').hidden=true;$('output').textContent='Gerando e verificando arquivos…';let d=await api('/build?mode='+$('mode').value,'');dir=d.output_directory;$('output').textContent='Verificado: '+d.files.join(' | ');$('open').hidden=false}catch(e){$('output').textContent=e.message}finally{$('build').disabled=false}});$('probe').onclick=()=>run(async()=>{try{$('probe').disabled=true;$('build').disabled=true;$('open').hidden=true;$('output').textContent='Gerando teste isolado das bases…';let d=await api('/players/probe?mode='+$('mode').value,{database:db()});dir=d.output_directory;$('output').textContent='Teste gerado: '+d.files.join(' | ')+'. Confira Lampard DB6667 ou Lampard DB6668 em jogo.';$('open').hidden=false}catch(e){$('output').textContent=e.message}finally{$('probe').disabled=false;$('build').disabled=false}});$('open').onclick=()=>run(async()=>{await api('/openOutput',{directory:dir})});run(refresh);</script></html>'''
